interface ScopeParameters {
  screenCount: number;
  hasCustomAuth: boolean;
  paymentIntegrations: number;
  databaseModels: number;
  requiresEdgeDeployment: boolean;
  hourlyRateINR: number;
}

export function calculateProjectEstimate(params: ScopeParameters): {
  estimatedHours: number;
  totalQuoteINR: number;
  deliveryWeeks: number;
} {
  let hours = 0;

  // UI components and responsive layout: ~6 hours per unique view
  hours += params.screenCount * 6;

  // Authentication: session handling, password reset, OAuth
  if (params.hasCustomAuth) hours += 16;

  // Payment gateway: webhooks, status verification, receipt generation
  hours += params.paymentIntegrations * 14;

  // Database schema, migrations, and CRUD endpoints: ~4 hours per model
  hours += params.databaseModels * 4;

  // Edge caching, SEO metadata, and Core Web Vitals optimization
  if (params.requiresEdgeDeployment) hours += 12;

  // Add 15% buffer for manual QA, browser testing, and staging review
  const totalHours = Math.round(hours * 1.15);
  const totalQuoteINR = totalHours * params.hourlyRateINR;
  const deliveryWeeks = Math.ceil(totalHours / 30); // based on 30 productive hrs/week

  return {
    estimatedHours: totalHours,
    totalQuoteINR,
    deliveryWeeks,
  };
}
